effect.frag.content:
uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  vec2 p = v_uv - 0.5;
  vec2 uv = v_uv + sin(p.yx * 20.0 + u_progress * TAU) * u_amount * 0.025;
  vec4 c = sourceAt(uv);
  vec3 tint = 0.5 + 0.5 * cos(TAU * (length(p) * 3.0 - u_progress) + vec3(0.0, 2.1, 4.2));
  c.rgb = mix(c.rgb, tint * c.a, u_amount * 0.6);
  fragColor = c;
}
